use crate::process;
use crate::template;
use anyhow::{Context, Result};
use std::fs;
use std::path::Path;

// Generated by build.rs: scans template/ project files at compile time,
// produces `pub static TEMPLATE_FILES: &[(&str, &str)]`.
include!(concat!(env!("OUT_DIR"), "/template_files.rs"));

/// Write all template files into `dest_dir`, processing directives and
/// applying variable substitution.
///
/// `selected` is the list of option names the user chose (e.g.
/// `["rtl8721f", "embassy"]`).  Variable bindings from each selected
/// option's `sets` map are merged into the template variable list.
pub fn generate(
    project_name: &str,
    sdk_path: &str,
    selected: &[&str],
    dest_dir: &Path,
) -> Result<()> {
    // Base variables always available in templates.
    let mut vars: Vec<(&str, &str)> = vec![("project-name", project_name), ("sdk-path", sdk_path)];

    // Collect extra variables from each selected option's `sets` map.
    let tmpl = template::load()?;
    let mut extra: Vec<(String, String)> = Vec::new();
    for opt in tmpl.flat_options() {
        if selected.contains(&opt.name.as_str()) {
            for (k, v) in &opt.sets {
                extra.push((k.clone(), v.clone()));
            }
        }
    }
    // Extend vars with owned strings kept alive in `extra`.
    let extra_refs: Vec<(&str, &str)> = extra
        .iter()
        .map(|(k, v)| (k.as_str(), v.as_str()))
        .collect();
    vars.extend_from_slice(&extra_refs);

    for (rel_path, content) in TEMPLATE_FILES {
        let target = dest_dir.join(rel_path);
        if let Some(parent) = target.parent() {
            fs::create_dir_all(parent)
                .with_context(|| format!("create dir {}", parent.display()))?;
        }

        // process_file returns Ok(None) when the INCLUDEFILE condition is false,
        // and Err on a malformed directive.
        let processed = process::process_file(content, &vars, selected)
            .with_context(|| format!("processing template {}", rel_path))?;
        if let Some(processed) = processed {
            fs::write(&target, processed).with_context(|| format!("write {}", target.display()))?;
        }
    }

    Ok(())
}
